  final case class Bytes(value: Array[Byte]) extends StringOrBytes

  def fromString(value: String): StringOrBytes = Str(value)
  def fromBytes(value: Array[Byte]): StringOrBytes = Bytes(value)
}

final class StringTokenizer(
  val encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[StringOrBytes] {

  override def tokenize(value: StringOrBytes): Token = value match {
    case StringOrBytes.Bytes(bytes) =>
      val strValue = new String(bytes, encoding)
      Token(normalizer(strValue), TokenType.STRING)
    case StringOrBytes.Str(str) =>
      Token(normalizer(str), TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(StringOrBytes.Str(value))

  def tokenize(value: Array[Byte]): Token = tokenize(StringOrBytes.Bytes(value))
}

final class NumericTokenizer(
  val precision: Int = 6,
  val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  private def formatDecimal(value: BigDecimal): String =
    value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString

  private def formatDouble(value: Double): String =
    f"$value%1.${precision}f"

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal => formatDecimal(bd)
      case bd: java.math.BigDecimal => formatDecimal(BigDecimal(bd))
      case d: Double => formatDouble(d)
      case f: Float => formatDouble(f.toDouble)
      case i: Byte => i.toString
      case i: Short => i.toString
      case i: Int => i.toString
      case i: Long => i.toString
      case other => other.toString
    }

    val originalType = value match {
      case _: Byte | _: Short | _: Int | _: Long => "int"
      case _: java.lang.Byte | _: java.lang.Short | _: java.lang.Integer | _: java.lang.Long => "int"
      case _: Float | _: Double => "float"
      case _: java.lang.Float | _: java.lang.Double => "float"
      case _: BigDecimal | _: java.math.BigDecimal => "Decimal"
      case null => "null"
      case other => other.getClass.getSimpleName
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> originalType))
  }
}

object TemporalTokenizer {
  val IsoFormat: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat: String = "yyyy-MM-dd"
}

final class TemporalTokenizer(formatStr: Option[String] = None)
  extends BaseTokenizer[Any] {

  def this(formatStr: String) = this(Option(formatStr))

  override def tokenize(value: Any): Token = {
    val fmt = formatStr.getOrElse {
      value match {
        case _: LocalDateTime => TemporalTokenizer.IsoFormat
        case _: LocalDate => TemporalTokenizer.DateFormat
        case _ => TemporalTokenizer.IsoFormat
      }
    }

    val formatter = DateTimeFormatter.ofPattern(fmt)

    val formatted = value match {
      case dt: LocalDateTime => dt.format(formatter)
      case d: LocalDate => d.format(formatter)
      case other => other.toString
    }

    Token(formatted, TokenType.TEMPORAL)
  }
}

final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: String): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Int): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Long): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)
  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: Tokenizable): Token = Token(value.toToken, TokenType.STRUCTURED)
  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)
    case n: BigDecimal => numericTokenizer.tokenize(n)
    case n: java.math.BigDecimal => numericTokenizer.tokenize(n)
    case n: Byte => numericTokenizer.tokenize(n)
    case n: Short => numericTokenizer.tokenize(n)
    case n: Int => numericTokenizer.tokenize(n)
    case n: Long => numericTokenizer.tokenize(n)
    case n: Float => numericTokenizer.tokenize(n)
    case n: Double => numericTokenizer.tokenize(n)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

