type JsonValue = Json

final class JsonTokenizer(val pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList.filter(_.nonEmpty)

    def descend(current: Json, remaining: List[String]): Option[Json] = remaining match {
      case Nil => Some(current)
      case head :: tail =>
        if (head.forall(_.isDigit)) {
          val idx = head.toInt
          current.asArray.flatMap { arr =>
            if (idx >= 0 && idx < arr.size) descend(arr(idx), tail) else None
          }
        } else {
          current.asObject.flatMap(_.apply(head)).flatMap(next => descend(next, tail))
        }
    }

    descend(value, parts).map(tokenize)
  }
}

// =========================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// =========================================================================

final class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def stripEdges(word: String): String = {
    val left = word.dropWhile(punctuation.contains)
    left.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) stripEdges(word) else word
    val normalized = if (lowercase) stripped.toLowerCase else stripped

    if (normalized.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(max) if normalized.length > max => normalized.take(max)
        case _ => normalized
      }
      if (truncated.isEmpty) None else Some(truncated)
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    val tokens = mutable.ListBuffer.empty[Token]

    words.zipWithIndex.foreach { case (word, idx) =>
      if (word.nonEmpty) {
        processToken(word).foreach { processed =>
          val token = Token(
            value = processed,
            tokenType = TokenType.STRING,
            metadata = Map("position" -> idx, "original" -> word)
          )
          tokens += token
        }
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    text.split("\\s+").foreach { word =>
      if (word.nonEmpty) {
        val start = text.indexOf(word, currentPos)
        val end = start + word.length

        processToken(word).foreach { processed =>
          result += ((processed, start, end))
        }

        currentPos = end
      }
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// =========================================================================
// Builder Pattern with Fluent Interface
// =========================================================================

final class TokenizerBuilder[T]() {
  private var normalizers: Vector[String => String] = Vector.empty
  private var validators: Vector[T => Boolean] = Vector.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers = normalizers :+ normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators = validators :+ validator
    this
  }

  def withMetadata(kv: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kv.toMap
    this
  }

  def build(): T => Token = {
    val capturedNormalizers = normalizers
    val capturedValidators = validators
    val capturedMetadata = metadata

    value: T => {
      capturedValidators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = capturedNormalizers.foldLeft(value.toString) { (current, norm) =>
        norm(current)
      }

      Token(normalized, TokenType.STRING, capturedMetadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

